using System; using System.IO; using UnityEngine;   [Serializable] public class PlayerSaveData {     public float x;     public float y;     public float z;     public float hp; }  public class PlayerSave : MonoBehaviour {     [Header("저장할 플레이어")]     [SerializeField] private Transform player;      [SerializeField] private Combat combat;      private string SavePath =>         Path.Combine(Application.persistentDataPath, "player-save.json");      private void Awake()     {         if (combat == null) combat = FindObjectOfType<Combat>();         if (player == null && combat != null && combat.player != null) player = combat.player.transform;     }      private void Update()     {         if (Input.GetKeyDown(KeyCode.F1))             Save();          if (Input.GetKeyDown(KeyCode.F2))             Load();     }      private void Save()     {         if (!CanAccessPlayer())             return;          PlayerSaveData data = new PlayerSaveData         {             x = player.position.x,             y = player.position.y,             z = player.position.z,             hp = combat.PlayerHealth         };          File.WriteAllText(SavePath, JsonUtility.ToJson(data, true));         Debug.Log($"저장했습니다: {SavePath}");     }      private void Load()     {         if (!File.Exists(SavePath))         {             Debug.Log("저장 파일이 없습니다.");             return;         }          if (!CanAccessPlayer())             return;          PlayerSaveData data = JsonUtility.FromJson<PlayerSaveData>(File.ReadAllText(SavePath));          player.position = new Vector3(data.x, data.y, data.z);          combat.SetPlayerHealthFromSave(Mathf.RoundToInt(data.hp));         Debug.Log($"불러왔습니다. HP: {data.hp}");     }      private bool CanAccessPlayer()     {         if (combat == null) combat = FindObjectOfType<Combat>();         if (player == null && combat != null && combat.player != null) player = combat.player.transform;         if (player == null || combat == null)         {             Debug.LogError("PlayerSave에 Combat와 Player가 필요합니다.");             return false;         }         return true;     } }